//! Table tests of `Global.serialize` where its write fails or meets the cost limit. sigmastate's writer adds
//! each put's cost to the evaluator before the put (v6.0.6 `methods.scala:1968-1983`,
//! `SigmaByteWriter.scala:45-174`), so the cost counter at a failure holds every put made before it, and a
//! write stops at the put whose cost crosses the limit.
//!
//! The rows are sigma-state 6.0.7's at activated version 3 (the round's `measure/rows/`, `out/*-jvm.txt`;
//! generated by `measure/tests/gen_rows_test.py`). The outcome and the cost counter are the jars'.
use crate::eval::test_util::jvm_text;
use crate::eval::{Env, Evaluable};
use ergotree_ir::chain::context::Context;
use ergotree_ir::ergo_tree::ErgoTreeVersion;
use ergotree_ir::mir::expr::Expr;
use ergotree_ir::mir::value::Value;
use ergotree_ir::serialization::sigma_byte_reader::from_bytes;
use ergotree_ir::serialization::sigma_byte_reader::SigmaByteRead;
use ergotree_ir::serialization::SigmaSerializable;
use sigma_test_util::force_any_val;

/// A row: its name in the round's row set, the expression's bytes, the tree version, the cost limit, then
/// the value as [`text`] prints it, `LIMIT` where the cost limit stops the evaluation or `ERR` for any other
/// failure, and the cost counter where the evaluation ended
type Row = (&'static str, &'static str, u8, u64, &'static str, u64);

/// A value as `jvm_text` prints it; of a collection of more than 100 items the first 100 and the length,
/// which is what the jars' probe prints
fn text(v: &Value<'_>) -> alloc::string::String {
    match v {
        Value::Coll(c) if c.len() > 100 => {
            let items: alloc::vec::Vec<_> = (0..100)
                .filter_map(|i| c.get_val(i))
                .map(|v| jvm_text(&v))
                .collect();
            alloc::format!("Coll({},…)#{}", items.join(","), c.len())
        }
        v => jvm_text(v),
    }
}

/// The rows whose outcome, value or cost counter is not the table's
#[allow(clippy::unwrap_used)]
fn wrong_rows(rows: &[Row]) -> alloc::vec::Vec<alloc::string::String> {
    let mut wrong = alloc::vec::Vec::new();
    for (name, body, version, limit, expected, cost) in rows {
        let version = ErgoTreeVersion::from(*version);
        let bytes = base16::decode(body.as_bytes()).unwrap();
        let expr = from_bytes(&bytes)
            .with_tree_version(version, Expr::sigma_parse)
            .unwrap();
        let mut ctx = force_any_val::<Context>();
        ctx.activated_script_version_byte = 3;
        ctx.tree_version.set(version);
        ctx.jit_cost.set(0);
        ctx.jit_cost_limit = Some(*limit);
        let res = expr.eval(&mut Env::empty(), &ctx);
        let got = match &res {
            Ok(v) => text(v),
            Err(e) if e.is_cost_error() => "LIMIT".into(),
            Err(_) => "ERR".into(),
        };
        let stopped_at = ctx.jit_cost_value();
        if got != *expected || stopped_at != *cost {
            wrong.push(alloc::format!(
                "{name} (limit {limit}): expected {expected} at {cost}, got {got} at {stopped_at}"
            ));
        }
    }
    wrong
}

