#[test]
fn a_refused_count_has_been_charged() {
    assert_eq!(COUNT_ROWS.len(), 34);
    let wrong = wrong_rows(COUNT_ROWS);
    assert!(
        wrong.is_empty(),
        "{} of {}:\n{}",
        wrong.len(),
        COUNT_ROWS.len(),
        wrong.join("\n")
    );
}

