#[test]
fn a_box_whose_tree_is_not_written_has_paid_for_its_value() {
    assert_eq!(BOX_ROWS.len(), 48);
    let wrong = wrong_rows(BOX_ROWS);
    assert!(
        wrong.is_empty(),
        "{} of {}:\n{}",
        wrong.len(),
        BOX_ROWS.len(),
        wrong.join("\n")
    );
}

